/**
 * Original scripted teaching examples. Replayed through the exact kernel;
 * demonstration sessions never earn rewards. No real-flight transfer claim.
 *
 * Frame storage is lossless per-axis delta / zigzag / unsigned-varint encoding.
 * It reduces optional-package size; decoded FlightAttempt.v1 data and identities
 * remain byte-for-byte equivalent to the historical JSON export.
 */
function decodeFrames({ count, data }) {
  const bytes = atob(data);
  const previous = [0, 0, 0, 0];
  let cursor = 0;
  const frames = Array.from({ length: count }, () =>
    previous.map((last, axis) => {
      let value = 0, multiplier = 1, digit;
      do {
        if (cursor >= bytes.length || multiplier > 2097152)
          throw new Error('Invalid teaching-example frame encoding');
        digit = bytes.charCodeAt(cursor++);
        value += (digit & 127) * multiplier;
        multiplier *= 128;
      } while (digit & 128);
      previous[axis] = last + (value % 2 ? -(value + 1) / 2 : value / 2);
      return previous[axis];
    }),
  );
  if (cursor !== bytes.length) throw new Error('Trailing teaching-example frame data');
  return frames;
}

